#!/bin/zsh
# Only the library (out/libmotolii.dylib), not the shells and checks edit.sh also builds: for a change in motolii.mm.
# Then restart the window (a native library cannot be hot reloaded).   ./build_lib.sh
cd "$(dirname "$0")"
source deps/build_lock.sh; build_lock "$@"   # (the machine's one build lock, taken here: deps/build_lock.sh)
HB=${HOMEBREW_PREFIX:-$(brew --prefix)}   # (where Homebrew is: /opt/homebrew on Apple silicon)
./deps/tree_sitter.sh || exit 1   # (tree-sitter and its JavaScript grammar, for community/js/js_returned.cpp)
KIT_EXTRA="-dynamiclib -install_name @rpath/libmotolii.dylib $(pkg-config --cflags --libs gstreamer-1.0 gstreamer-app-1.0 gstreamer-video-1.0 gstreamer-pbutils-1.0) -lgltfio -lgltfio_core -ldracodec -DSQLITE_ENABLE_SESSION -DSQLITE_ENABLE_PREUPDATE_HOOK -I$HB/opt/sqlite/include $HB/opt/sqlite/lib/libsqlite3.dylib $PWD/physics/jolt.cpp $PWD/community/js/script.cpp $PWD/community/js/js_returned.cpp -I$PWD/third_party/tree-sitter/lib/include $PWD/out/ts_lib.o $PWD/out/ts_js_parser.o $PWD/out/ts_js_scanner.o -I$PWD/third_party/thermion_frame/include -I$PWD/third_party/qdtsne/include -I$PWD/third_party/scipy_lsap $PWD/third_party/scipy_lsap/rectangular_lsap.cpp $PWD/third_party/thermion_frame/FrameScheduler.cpp -framework CoreVideo $PWD/community/shaders/splatfx.cpp $PWD/community/shaders/three_isf.cpp $PWD/community/js/solid_three.cpp $PWD/community/shaders/hydra_isf.cpp $PWD/media/midi_roll.cpp -lmatp $PWD/out/isf.o $PWD/out/aviutl.o -I$HB/opt/luajit/include/luajit-2.1 -L$HB/opt/luajit/lib -lluajit-5.1 -Wl,-rpath,$HB/opt/luajit/lib -I$HB/opt/quickjs-ng/include -L$HB/opt/quickjs-ng/lib -lqjs -Wl,-rpath,$HB/opt/quickjs-ng/lib -I$HB/opt/onnxruntime/include/onnxruntime -L$HB/opt/onnxruntime/lib -lonnxruntime -Wl,-rpath,$HB/opt/onnxruntime/lib -I$PWD/third_party/physics/JoltPhysics -DJPH_CROSS_PLATFORM_DETERMINISTIC -DJPH_DEBUG_RENDERER -DJPH_OBJECT_LAYER_BITS=16 -DJPH_OBJECT_STREAM -DJPH_PROFILE_ENABLED -ffp-contract=off $PWD/third_party/physics/JoltPhysics/jbuild/libJolt.a $PWD/out/flashes.o $PWD/third_party/iris/lib/libiris.a -L$PWD/third_party/iris/opencv_out/lib -lopencv_features2d -lopencv_videoio -lopencv_imgcodecs -lopencv_imgproc -lopencv_core -L$PWD/third_party/iris/opencv_out/lib/opencv4/3rdparty -ltegra_hal -lz $(pkg-config --libs libavformat libavcodec libavutil) -framework AVFoundation -framework CoreMedia -framework CoreGraphics -framework Accelerate" BUILDONLY=1 ./gpu/kit_wgpu.sh motolii
mv out/motolii_wgpu out/libmotolii.dylib
